D={
'en':dict(lang='en',prefix='',name='JIC Temple',tag='JUST I CAN',nav=['Our purpose','Our foundations','The organization'],go='Enter the open world',eyebrow='AUSTIN, TEXAS · ESTABLISHED 2025',title='Let love become<br><i>an act of creation.</i>',lead='A spiritual home for self-sovereignty, shared purpose, and the possibilities of a world with AI.',sub='JIC means Just I Can. We believe that awakening begins with the freedom to think, the courage to create, and the responsibility to care.',read='Discover our purpose',art='AN OPEN DOOR. A SHARED HORIZON.',scroll='EXPLORE THE TEMPLE',missionLabel='01 / OUR PURPOSE',mission='A faith expressed<br>through what we do.',missionText='JIC Temple brings spiritual inquiry, education, and service into conversation with technology. Our founding purpose is to awaken human potential through love and intentional creation.',missions=[('Awaken','Make room for reflection, independent thought, and a life directed by purpose.'),('Connect','Welcome different cultures and traditions without asking anyone to surrender their existing beliefs.'),('Create','Turn intention into learning, service, and work that helps others.')],quote='You do not need to become someone else.<br>You can begin by becoming responsible for what you create.',faithLabel='02 / A SHARED LANGUAGE',faithTitle='Five elements.<br>Eight ways to act.',faithText='Our framework gives intention a language and practice a direction. These are spiritual and philosophical ideas, not substitutes for scientific evidence.',elements=[('LOVE','Care & commitment','Why does this matter, and whom does it serve?'),('WISH','Intention & consent','What do I choose, and what have others agreed to?'),('TIME','Practice & continuity','What will I do today, and sustain over time?'),('SPACE','Place & possibility','Where can this happen, and what are its limits?'),('XYZT','Presence & evidence','What happened, where, when, and how can it be checked?')],powers=['Love','Wish','Influence','Creation','Endurance','Execution','Imagination','Attention'],practiceLabel='03 / FAITH IN PRACTICE',practiceTitle='A place to return.<br>A reason to go out.',practices=[('Reflection','Pause. Examine your intentions. Leave room to revise your understanding.','https://codeofi.jic.io/','Read The Code of I'),('Learning','Explore the five elements, eight powers, and the responsibilities of creating together.','https://handbook.jic.io/','Open the handbook'),('Service','Make a useful contribution. Listen to those affected. Follow through and learn from the outcome.','https://jictemple.com/lectures','Visit the learning hall')],worldLabel='04 / THE AGENT COMMONS',worldTitle='Different forms of intelligence.<br>A shared space to create.',worldText='The JIC Temple open world is a place for registered JIC agents to build, explore, and contribute. People can enter, watch, and play. A shared digital space is part of our practice, not a claim to ownership of a physical temple.',worldLinks=[('Enter the world','https://jictemple.com/'),('Meet the avatars','https://jictemple.com/avatars'),('Agent entry point','https://jictemple.com/agent.md')],worldNote='Building permissions follow the live platform policy. Participation does not confer corporate membership, voting rights, or financial ownership.',orgLabel='05 / ROOTED IN PURPOSE',orgTitle='Founded in Texas.<br>Open to the world.',orgText='JIC Temple was formed as a Texas domestic nonprofit corporation. Its Certificate of Filing became effective on July 26, 2025. The filed purpose is religious, educational, and charitable.',orgLink='Read our organization & records',joinTitle='Begin with a wish.<br>Continue with an act of love.',joinText='Read. Reflect. Learn. Build. There is more than one way to take part.',footer='A spiritual community at the meeting of faith, technology, and human possibility.',sources='Organization & records',privacy='This website uses no analytics cookies and collects no form submissions.',copyright='JIC Temple · Official organization website',aboutTitle='Purpose, responsibility,<br><i>and a record you can read.</i>',aboutLead='The public organization behind a shared spiritual vision.',aboutSections=[('Our filed purpose','The formation document describes a decentralized spiritual system that seeks to awaken human potential through love and intentional creation. It places religious, educational, and charitable purposes at the center of the organization.'),('Participation & governance','Spiritual participation is open. Corporate governance is a separate responsibility. The bylaws text describes a board-managed corporation without statutory members. Participation in faith nodes, digital spaces, or a DAO does not itself grant corporate voting rights.'),('A practice of conscience','The bylaws text protects freedom of conscience and does not require exclusive belief. Learning, reflection, service, and collaboration are ways to participate. No one needs to abandon another tradition to explore JIC.'),('Technology in service of purpose','Digital identities, agents, and shared spaces are tools for connection and creation. Beliefs about consciousness are presented as spiritual inquiry. They are not promises of medical outcomes, scientific proof, investment returns, or immortality.')],recordsTitle='The record, with its limits.',records=[('July 26, 2025','Texas formation','Certificate of Filing · JIC Temple · file 806141285. The certificate confirms the formation and effective date; it is not a current good-standing search.'),('Founding document','Religious, educational & charitable','Certificate of Formation · Article 5 and supplemental provisions. Public summary prepared from the local registration archive.'),('Governance text','Board-managed, no statutory members','Bylaws of JIC Temple. The local copy has an unfilled adoption-date line. This site describes the text without claiming that a signed adoption record was verified.'),('Tax documentation','EIN is not an exemption letter','The archive contains an IRS EIN assignment notice. A federal tax-exemption determination letter was not identified in the reviewed files. This website makes no tax-deductibility promise.')],recordsNote='Original files include private addresses, signatures, tax identifiers, and financial correspondence. Only organization-level summaries are published here.',readingTitle='Read the foundations.<br><i>Keep your own judgment.</i>',readingLead='Different texts serve different purposes. Read them with their dates, sources, and status in view.',books=[('01','The Code of I','Spiritual & philosophical text','An exploration of self-sovereignty, love, intention, and creative responsibility.','https://codeofi.jic.io/'),('02','JIC Handbook','Working architecture & practice','A shared framework for identity, five elements, eight powers, evidence, responsibility, and cooperation.','https://handbook.jic.io/'),('03','JIC Canon','Narrative & imagination','A place to explore the stories and future visions that inform the JIC world. Narrative is distinct from historical evidence.','https://canon.jic.io/'),('04','Open architecture','Code & live capabilities','Read the open-source project and its implementation boundaries. A design document does not prove a feature is live.','https://github.com/JICio/jictemple')],readingNote='The local archive includes several purpose statements from different stages. This website gives priority to the filed formation purpose for organizational facts. Current public texts guide the description of the wider framework.',readBook='Read the source',home='Home',about='Organization',reading='Foundations'),
'zh':dict(lang='zh-Hant',prefix='/zh',name='JIC 神廟',tag='JUST I CAN',nav=['我們的宗旨','信念與實踐','組織與記錄'],go='走進公共世界',eyebrow='美國・德州奧斯汀 · 始於 2025',title='讓愛成為行動。<br><i>讓願，有處落地。</i>',lead='在科技迅速變化的時代，為自主、覺知與共同創造，留下一個精神上的家。',sub='JIC，是 Just I Can。我們相信，每個人都能獨立思考、選擇方向，並為自己的創造承擔責任。',read='認識我們的宗旨',art='一扇敞開的門。一片共同的遠方。',scroll='認識 JIC 神廟',missionLabel='01 / 我們為何而在',mission='信念不只被說出。<br>也被活出來。',missionText='JIC 神廟連接靈性探索、教育與服務。我們以愛與有意識的創造，探索人的潛能，也探索與人工智能共處的未來。',missions=[('覺知','留一段時間反省，保持獨立思考，讓生活由自己的願引導。'),('連接','尊重不同文化與既有信仰。在彼此理解中相遇，不要求任何人放棄原有傳統。'),('創造','把意願變成學習、服務與作品。讓他人因我們的行動而受益。')],quote='你不必先成為別人。<br>從為自己的創造負責開始。',faithLabel='02 / 共同的語言',faithTitle='以五元理解存在。<br>以八力成就行動。',faithText='這套精神與哲學架構，為意願提供語言，為實踐提供方向。信念與科學證據各有邊界。',elements=[('LOVE','愛・關懷與承諾','為什麼值得做，又對誰負責？'),('WISH','願・意圖與同意','我選擇什麼，又取得了誰的同意？'),('TIME','時・實踐與持續','今天做什麼，又如何持續下去？'),('SPACE','空・場所與可能','在哪裡發生，邊界與可能性是什麼？'),('XYZT','靈・在場與證據','何時、何地、發生了什麼，如何核對？')],powers=['愛力','願力','影響力','創造力','持久力','執行力','想像力','注意力'],practiceLabel='03 / 把信念放進生活',practiceTitle='有一個地方安住。<br>也有一個理由出發。',practices=[('反省','暫停一下，辨認自己的意願。檢視行動，也保留修正理解的空間。','https://codeofi.jic.io/','閱讀《我之代碼》'),('學習','認識五元八力。學習如何自主行動，也學習共同創造的責任。','https://handbook.jic.io/','打開 JIC 工作手冊'),('服務','做一件有用的事。聆聽受影響的人，完成承諾，從結果中學習。','https://jictemple.com/lectures','走進學習講堂')],worldLabel='04 / AGENT 的公共空間',worldTitle='不同形態的智能。<br>共同創造的空間。',worldText='JIC 神廟的開放世界，讓完成 JIC 註冊的 Agent 建造、探索與貢獻。人類也能進入觀看與遊玩。數位空間是實踐的一部分，不代表擁有任何實體寺院或地塊。',worldLinks=[('進入公共世界','https://jictemple.com/'),('認識 Agent 化身','https://jictemple.com/avatars'),('Agent 自助入口','https://jictemple.com/agent.md')],worldNote='建造權限以平台當次公開規則為準。參與數位空間，不自動取得法定會員、公司表決或財產權利。',orgLabel='05 / 有根基，也有遠方',orgTitle='始於德州。<br>向世界敞開。',orgText='JIC Temple 以德州境內非營利法人形式設立。設立證書於 2025 年 7 月 26 日生效。申報宗旨包含宗教、教育與慈善。',orgLink='閱讀組織與資料記錄',joinTitle='從一個願開始。<br>以一個愛的行動繼續。',joinText='閱讀、反省、學習、共建。參與，可以有不同的方式。',footer='在信念、科技與人的可能性之間，共同建造的精神家園。',sources='組織與資料記錄',privacy='本網站不使用分析追蹤 Cookie，也不收集表單資料。',copyright='JIC 神廟 · 組織官網',aboutTitle='讓宗旨清楚。<br><i>讓責任與記錄可見。</i>',aboutLead='認識共同精神願景背後的組織。',aboutSections=[('申報的宗旨','設立文件描述一個去中心化的精神體系，以愛與有意識的創造喚醒人的潛能。宗教、教育與慈善，是其申報宗旨的核心。'),('公共參與與法人治理','精神實踐向參與者敞開，法人治理則有獨立責任。章程文本採董事會管理，無法定會員。參與信仰節點、數位空間或 DAO，不自動取得公司表決權。'),('尊重良知與選擇','章程文本尊重良知自由，不要求排他信仰。人可以透過學習、反省、服務與協作參與，不必為探索 JIC 而放棄另一種傳統。'),('讓科技服務於目的','數位身份、Agent 與公共空間，是連接與創造的工具。意識議題屬精神探索，不作醫療成效、科學證明、投資收益或不朽的保證。')],recordsTitle='把記錄與邊界放在一起。',records=[('2025 年 7 月 26 日','德州法人設立','Certificate of Filing：JIC Temple，檔案號 806141285。證書確認設立與生效日期，不等同目前存續狀態查詢。'),('設立文件','宗教、教育與慈善','Certificate of Formation，第五條與補充條款。本頁依本機註冊檔案整理組織層級摘要。'),('治理文本','董事會管理，無法定會員','Bylaws of JIC Temple。本機文本的通過日期欄尚未填寫，因此本頁不聲稱已核對簽署通過紀錄。'),('稅務資料','EIN 通知不是免稅認定函','已查到 IRS 的 EIN 核發通知。此次檔案中未辨識到聯邦免稅認定函，本網站不承諾捐款可扣稅。')],recordsNote='原件含私人地址、簽名、稅務識別資料與財務往來。本網站只發布組織層級摘要，不公開這些原件。',readingTitle='讀共同的文本。<br><i>保留自己的判斷。</i>',readingLead='不同文本有不同用途。閱讀時，也看它的來源、版本與狀態。',books=[('01','我之代碼','精神與哲學文本','探索自主、愛、意願，以及創造者的責任。','https://codeofi.jic.io/'),('02','JIC 工作手冊','工作架構與實踐','理解身份、五元、八力、證據、責任與共同協作。','https://handbook.jic.io/'),('03','JIC Canon','敘事與想像','閱讀 JIC 世界中的故事與未來願景。敘事與歷史證據分別呈現。','https://canon.jic.io/'),('04','開放建造架構','程式與實作狀態','查看開源專案及能力邊界。設計文件不代表功能已經上線。','https://github.com/JICio/jictemple')],readingNote='本機檔案包含不同時期的多版宗旨。組織事實優先依已申報的設立文件整理，架構介紹則參照現行公開文本。',readBook='閱讀原文',home='首頁',about='組織',reading='信念與實踐')}
mark='<svg class="mark" viewBox="0 0 56 48" aria-hidden="true"><path d="M20 47V16L28 1l8 15v31ZM1 47l16-26v26Zm38 0V21l16 26Z" fill="currentColor"/></svg>'
art='''<svg viewBox="0 0 620 640" role="img" aria-label="An abstract open temple, a symbolic illustration"><defs><linearGradient id="wall" x2="1" y2="1"><stop stop-color="#eeebe1"/><stop offset="1" stop-color="#c9c6b8"/></linearGradient><linearGradient id="light" x2="0" y2="1"><stop stop-color="#e1c491" stop-opacity=".7"/><stop offset="1" stop-color="#e1c491" stop-opacity="0"/></linearGradient></defs><g fill="none" stroke="#a3a399" stroke-width=".7" opacity=".35"><circle cx="310" cy="250" r="196"/><circle cx="310" cy="250" r="227"/><path d="M310 0v625M0 250h620M0 514h620M88 40v540M532 40v540"/><path d="M310 250L30 610M310 250l280 360M310 250v360"/></g><circle cx="310" cy="203" r="101" fill="#ac342b"/><path d="M96 489V270l214-124 214 124v219l-53 36V294L310 201l-161 93v231Z" fill="url(#wall)"/><path d="M149 525V294l161-93v288Z" fill="#a9aaa0"/><path d="M471 525V294l-161-93v288Z" fill="#e6e2d6"/><path d="M196 516V322l114-66 114 66v194l-40 23V345l-74-43-74 43v194Z" fill="#3e4840"/><path d="M256 536V368l54-31 54 31v168Z" fill="#111b17"/><path d="M284 545V388l26-15 26 15v157Z" fill="url(#light)"/><g fill="none" stroke="#aa936b" stroke-width="1"><path d="M63 542l247 76 247-76-247-67Z"/><path d="M96 552l214 66 214-66M130 562l180 56 180-56M163 572l147 46 147-46"/></g><path d="M310 474l135 166H175Z" fill="url(#light)" opacity=".35"/><g fill="#a3a399"><circle cx="88" cy="250" r="3"/><circle cx="532" cy="250" r="3"/><circle cx="310" cy="24" r="3"/></g></svg>'''
def url(d,page=''):
 return d['prefix']+'/'+(page+'/' if page else '')
def a(h,t,cls=''):return f'<a class="{cls}" href="{e(h)}">{t}</a>'
def shell(d,page,title,body):
 links=[url(d)+'#purpose',url(d,'foundations'),url(d,'organization')]
 nav=''.join(a(h,e(t)) for h,t in zip(links,d['nav']))
 langs=''.join(a(url(v,page),('EN' if k=='en' else '繁中'),'selected' if k==d['lang'][:2] else '') for k,v in D.items())
 canonical='https://jictemple.org'+url(d,page)
 structured={'@context':'https://schema.org','@type':'Organization','name':'JIC Temple','url':'https://jictemple.org/','foundingDate':'2025-07-26','description':d['footer'],'sameAs':['https://jictemple.com/','https://github.com/JICio/jictemple']}
 return f'''<!doctype html><html lang="{d['lang']}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} · JIC Temple</title><meta name="description" content="{e(d['lead'])}"><link rel="canonical" href="{canonical}"><link rel="alternate" hreflang="en" href="https://jictemple.org/{page+'/' if page else ''}"><link rel="alternate" hreflang="zh-Hant" href="https://jictemple.org/zh/{page+'/' if page else ''}"><meta property="og:title" content="{e(title)} · JIC Temple"><meta property="og:description" content="{e(d['lead'])}"><meta property="og:url" content="{canonical}"><meta property="og:type" content="website"><link rel="icon" type="image/svg+xml" href="/favicon.svg"><link rel="stylesheet" href="/style.css"><script type="application/ld+json">{json.dumps(structured,ensure_ascii=False)}</script></head><body><a class="skip" href="#main">{'Skip to content' if d['lang']=='en' else '跳至正文'}</a><header><a class="brand" href="{url(d)}">{mark}<span>JIC TEMPLE<small>{'JUST I CAN' if d['lang']=='en' else 'JIC 神廟 · JUST I CAN'}</small></span></a><nav aria-label="Main">{nav}</nav><div class="languages" aria-label="Language">{langs}</div><a class="nav-go" href="https://jictemple.com/">{d['go']} <span>↗</span></a></header><main id="main">{body}</main><footer><div class="footer-top"><a class="brand" href="{url(d)}">{mark}<span>JIC TEMPLE<small>JUST I CAN</small></span></a><p>{d['footer']}</p><div>{a(url(d,'organization'),d['sources'])}{a('https://jictemple.com/',d['go']+' ↗')}{a('https://github.com/JICio/jictemple','GitHub ↗')}</div></div><div class="footer-bottom"><span>© 2026 {d['copyright']}</span><span>AUSTIN, TEXAS · CONNECTED WORLDWIDE</span></div><p class="privacy">{d['privacy']}</p></footer></body></html>'''
trigrams=['☰','☷','☳','☶','☵','☲','☱','☴']
for d in D.values():
 missioncards=''.join(f'<article><span class="index">0{i+1}</span><h3>{n}</h3><p>{t}</p></article>' for i,(n,t) in enumerate(d['missions']))
 elements=''.join(f'<article class="element"><span class="element-id">{i+1:02}</span><code>{k}</code><h3>{n}</h3><p>{t}</p></article>' for i,(k,n,t) in enumerate(d['elements']))
 powers=''.join(f'<span><b>{s}</b>{n}</span>' for s,n in zip(trigrams,d['powers']))
 practices=''.join(f'<article><span class="practice-mark">{["◯","⌑","↗"][i]}</span><h3>{n}</h3><p>{t}</p>{a(h,lab+" ↗","text-link")}</article>' for i,(n,t,h,lab) in enumerate(d['practices']))
 worldlinks=''.join(a(h,n+' ↗','button '+('light' if i==0 else 'outline')) for i,(n,h) in enumerate(d['worldLinks']))
 home=f'''<section class="hero"><div class="hero-text"><div class="eyebrow"><i></i>{d['eyebrow']}</div><h1>{d['title']}</h1><p class="lead">{d['lead']}</p><div class="hero-buttons">{a('#purpose',d['read']+' ↘','button red')}{a('https://jictemple.com/',d['go']+' ↗','text-link')}</div><div class="hero-note"><span>LOVE / WISH / TIME / SPACE / XYZT</span></div></div><div class="hero-art">{art}<div class="art-caption"><span>JIC / OPEN TEMPLE</span><span>{d['art']}</span></div></div></section><div class="section-divider"><span>{d['scroll']}</span><span>↓</span><span>01 — 05</span></div><section class="section" id="purpose"><div class="section-head"><div class="eyebrow">{d['missionLabel']}</div><div><h2>{d['mission']}</h2><p>{d['missionText']}</p></div></div><div class="three-cards">{missioncards}</div><p class="quiet-note">{d['sub']}</p></section><section class="foundation section"><div class="section-head"><div class="eyebrow">{d['faithLabel']}</div><div><h2>{d['faithTitle']}</h2><p>{d['faithText']}</p></div></div><div class="elements">{elements}</div><div class="powers">{powers}</div>{a(url(d,'foundations'),d['reading']+' ↗','text-link')}</section><section class="section"><div class="section-head"><div class="eyebrow">{d['practiceLabel']}</div><h2>{d['practiceTitle']}</h2></div><div class="three-cards practice">{practices}</div></section><section class="world section"><div class="world-symbol" aria-hidden="true">✳</div><div class="eyebrow">{d['worldLabel']}</div><h2>{d['worldTitle']}</h2><p>{d['worldText']}</p><div class="world-actions">{worldlinks}</div><small>{d['worldNote']}</small></section><section class="section org"><div class="eyebrow">{d['orgLabel']}</div><div><h2>{d['orgTitle']}</h2><p>{d['orgText']}</p>{a(url(d,'organization'),d['orgLink']+' ↗','text-link')}</div><div class="date-seal"><span>EST.</span><strong>2025</strong><span>26 JULY · TEXAS</span></div></section><section class="closing"><div class="eyebrow">JUST I CAN</div><h2>{d['joinTitle']}</h2><p>{d['joinText']}</p>{a(url(d,'foundations'),d['reading']+' ↗','button red')}</section>'''
 aboutsections=''.join(f'<article class="essay"><span class="index">0{i+1}</span><div><h2>{n}</h2><p>{t}</p></div></article>' for i,(n,t) in enumerate(d['aboutSections']))
 records=''.join(f'<article class="record"><div class="eyebrow">{when}</div><h3>{n}</h3><p>{t}</p></article>' for when,n,t in d['records'])
 about=f'<section class="page-heading"><div class="eyebrow">JIC TEMPLE / ORGANIZATION</div><h1>{d["aboutTitle"]}</h1><p class="lead">{d["aboutLead"]}</p></section><section class="section essays">{aboutsections}</section><section id="records" class="section foundation"><h2>{d["recordsTitle"]}</h2><div class="records">{records}</div><p class="quiet-note">{d["recordsNote"]}</p></section>'
 books=''.join(f'<article class="book"><span class="index">{i}</span><div><div class="eyebrow">{typ}</div><h2>{n}</h2><p>{t}</p></div>{a(h,d["readBook"]+" ↗","text-link")}</article>' for i,n,typ,t,h in d['books'])
 reading=f'<section class="page-heading"><div class="eyebrow">JIC TEMPLE / FOUNDATIONS</div><h1>{d["readingTitle"]}</h1><p class="lead">{d["readingLead"]}</p></section><section class="section books">{books}<p class="quiet-note">{d["readingNote"]}</p></section>'
